void Rebuffer::reportEvolveCounters(utl::Logger* logger)
{
  logger->report("RSZ_EVOLVE root_evals fired={}",
                 g_evolve_root_evals.exchange(0));
  logger->report("RSZ_EVOLVE multi_viol fired={}",
